class Container {
    using Data_T = int;
    void process(int i) { /* Outer context */ }

    class Nested {
        // Hiding the outer definition:
        using Data_T = double;

        void execute(int x);
    };
};

// Scope search starts at Nested, then Container, then global.
void Container::Nested::execute(int x) {
    // 1. Nested::Data_T resolves to double (Hiding)
    Data_T local_data = 1.0; 

    // 2. process() is not in Nested, lookup continues to Container.
    process(x); // Calls Container::process(int)

    // Explicit access (Bypassing Name Hiding):
    Container::Data_T outer_int = 5;
}
